// Posters and validation are generated by default; pass --video to also export MP4.
import fs from 'node:fs/promises';import path from 'node:path';import {fileURLToPath,pathToFileURL} from 'node:url';import {spawn} from 'node:child_process';import {once} from 'node:events';import assert from 'node:assert/strict';import sharp from 'sharp';
const dir=path.dirname(fileURLToPath(import.meta.url)),bundle=path.resolve(process.argv[2]),temp=path.join(dir,'temp/image-nested-clip'),out=path.resolve(dir,'../IMAGE/07-SW-Overview');await fs.mkdir(temp,{recursive:true});
const trace=JSON.parse(await fs.readFile(path.join(dir,'image-nested-clip-trace.txt'),'utf8')),variant=JSON.parse(await fs.readFile(path.join(dir,'image-nested-clip-variant.txt'),'utf8'));
const source=await fs.readFile(path.join(dir,'sw-image-nested-clip.lua'),'utf8'),oldSource=await fs.readFile(path.join(dir,'sw-image-clip-tasks.lua'),'utf8');
const lua=v=>Array.isArray(v)?'{'+v.map(lua).join(',')+'}':v&&typeof v==='object'?'{'+Object.entries(v).map(([k,v])=>`${k}=${lua(v)}`).join(',')+'}':JSON.stringify(v);assert(source.includes('local nested='+lua(trace)));
const {createTMath}=await import(pathToFileURL(path.join(bundle,'client.js')));const runtime=await createTMath('return tmath.scene{theme="pro_white"}','bootstrap.lua',{renderEngine:'cpu',wasmBinary:await fs.readFile(path.join(bundle,'tmath-wasm.wasm'))});runtime.font('Pretendard',await fs.readFile(path.join(bundle,'Pretendard.ttf')));
const rgb=v=>[v&255,(v>>>8)&255,(v>>>16)&255];let checks=0;const pixel=(b,w,x,y)=>[...b.subarray((Math.floor(y)*w+Math.floor(x))*4,(Math.floor(y)*w+Math.floor(x))*4+3)];const eq=(a,b,id)=>{assert(a.every((v,i)=>Math.abs(v-b[i])<=1),`${id}: ${a}/${b}`);checks++;};
try{
 runtime.loadLua(oldSource,'previous-clip.lua');const oldFinal=Buffer.from(runtime.render(runtime.duration,true));
 runtime.loadLua(source,'sw-image-nested-clip.lua');const [width,height]=runtime.size(),duration=runtime.duration,frames=Math.ceil(duration*30)+1;
 const first=Buffer.from(runtime.render(0,true));assert.equal(first.length,oldFinal.length);let seamMax=0,seamPixels=0;for(let i=0;i<first.length;i++){const d=Math.abs(first[i]-oldFinal[i]);seamMax=Math.max(seamMax,d);if(d)seamPixels++;}assert(seamMax<=1,`continuity mismatch ${seamMax}, ${seamPixels} channels`);
 let margin=Infinity;const labels=new Set();for(let f=0;f<frames;f++){const objects=runtime.layoutReport(Math.min(f/30,duration),4).objects,texts=[];for(const o of objects){if(o.type==='text')assert(o.id.startsWith('label_'));if(!o.visible||o.type==='group')continue;const b=o.paintBounds;assert(b&&b.width>0&&b.height>0);const m=Math.min(b.x,b.y,width-b.x-b.width,height-b.y-b.height);margin=Math.min(margin,m);assert(m>=4,'overflow '+o.id);if(o.type==='text'){texts.push(o);labels.add(o.id);}}for(let i=0;i<texts.length;i++)for(let j=i+1;j<texts.length;j++){const a=texts[i].paintBounds,b=texts[j].paintBounds;assert(Math.max(a.x-b.x-b.width,b.x-a.x-a.width)>=4||Math.max(a.y-b.y-b.height,b.y-a.y-a.height)>=4,`text overlap ${texts[i].id}/${texts[j].id}`);}}
 let memory=trace.firstPixels.slice();const check=(time,name)=>{const b=Buffer.from(runtime.render(time,true));for(let y=0;y<trace.h;y++)for(let x=0;x<trace.w;x++)eq(pixel(b,width,1670+(x+.5)*44,220+(y+.5)*44),rgb(memory[y*trace.stride+x]),name);for(let y=0;y<trace.ih;y++)for(let x=0;x<trace.iw;x++)eq(pixel(b,width,900+(x+trace.tx+.5)*44,220+(y+trace.ty+.5)*44),rgb(trace.source[y*trace.iw+x]),'retained Bitmap');};
 check(0,'continuity');let t=2+.15+.15+.4+.8+.15+.01+.15+.15+trace.clipB.length*.035+.4;check(t,'second clip prepared, old Surface retained');const samples=[0,t];
 t+=.1+.15+.25+.1+.6;check(t,'raw image rebuilt');t+=.1+.15+.25+.1+.6;check(t,'circle reapplied');t+=.1;
 for(let y=0;y<trace.h;y++){t+=.08+.25+.3+.08;check(t,`second intersection row ${y}, no Surface write`);}
 t+=.15+.7;check(t,'final RLE ready');samples.push(t);t+=.15+.15+.2;memory.fill(trace.background);check(t,'redraw background');
 for(let i=0;i<trace.finalRle.length;i++){const s=trace.finalRle[i];t+=.06+.04;const moving=Buffer.from(runtime.render(t+.11,true));for(let j=0;j<s.len;j++)eq(pixel(moving,width,900+(s.x+j+.5)*44+385,220+(s.y+.5)*44),rgb(trace.source[(s.y-trace.ty)*trace.iw+s.x+j-trace.tx]),'moving source color');t+=.22+.12+.06;trace.writes[i].forEach((v,j)=>memory[s.y*trace.stride+s.x+j]=v);check(t+.02,`final span ${i}`);t+=(s.len>=4?.3:.06)+.06;}
 assert.deepEqual(memory,trace.finalPixels);assert(Math.abs(duration-(t+3.5))<.002);check(duration,'final');samples.push(duration);
 for(const [prefix,base,spans]of[['clip',130,trace.clipA],['second',1670,trace.clipB],['nested',900,trace.finalRle]])for(const [i,s]of spans.entries()){const b=runtime.bounds(`${prefix}_span_${i+1}_begin`,duration),l=runtime.bounds(`${prefix}_span_${i+1}_len`,duration);assert(Math.abs(b.x+b.width/2-(base+(s.x+.5)*44))<1);assert(Math.abs(l.width-s.len*44)<3);}
 const dense=spans=>{const a=new Array(trace.stride*trace.h).fill(0);for(const s of spans)for(let x=s.x;x<s.x+s.len;x++)a[s.y*trace.stride+x]=s.coverage;return a;};const before=dense(trace.firstRle),after=dense(trace.finalRle);assert(after.every((v,i)=>v<=before[i]));
 runtime.loadLua(source.replace('local nested='+lua(trace),'local nested='+lua(variant)),'nested-variant.lua');const changed=Buffer.from(runtime.render(runtime.duration,true));let differences=0;for(let y=0;y<trace.h;y++)for(let x=0;x<trace.w;x++){const at=y*trace.stride+x;eq(pixel(changed,width,1670+(x+.5)*44,220+(y+.5)*44),rgb(variant.finalPixels[at]),'independent cut variant');if(variant.finalPixels[at]!==trace.finalPixels[at])differences++;}assert(differences>0);runtime.loadLua(source,'sw-image-nested-clip.lua');
 const report={width,height,duration,frames,framesAudited:frames,labels:labels.size,minMargin:margin,pixelChecks:checks,seamMax,seamChangedChannels:seamPixels,firstSpans:trace.firstRle.length,secondClipSpans:trace.clipB.length,finalSpans:trace.finalRle.length,beforeCoveredPixels:before.filter(Boolean).length,afterCoveredPixels:after.filter(Boolean).length,variantDifferences:differences};console.log(JSON.stringify(report));await fs.writeFile(path.join(temp,'review.txt'),JSON.stringify(report,null,2)+'\nNo inline raster review; thread budget exhausted.\n');
 for(const [i,time]of samples.entries())await sharp(Buffer.from(runtime.render(time,true)),{raw:{width,height,channels:4}}).png().toFile(path.join(temp,'review-'+i+'.png'));
 await sharp(Buffer.from(runtime.render(0,true)),{raw:{width,height,channels:4}}).webp({lossless:true}).toFile(path.join(out,'image-nested-clip.webp'));
 if(!process.argv.includes('--preview') && process.argv.includes('--video')){const ff=spawn('ffmpeg',['-hide_banner','-loglevel','error','-y','-f','rawvideo','-pixel_format','rgba','-video_size',`${width}x${height}`,'-framerate','30','-i','pipe:0','-an','-c:v','libx264','-preset','medium','-crf','20','-pix_fmt','yuv420p','-movflags','+faststart',path.join(out,'image-nested-clip.mp4')],{stdio:['pipe','inherit','inherit']});const end=once(ff,'close');for(let f=0;f<frames;f++){if(!ff.stdin.write(Buffer.from(runtime.render(Math.min(f/30,duration),true))))await once(ff.stdin,'drain');if(f%180===0)console.log(`${f}/${frames}`);}ff.stdin.end();const [code]=await end;assert.equal(code,0);}
}finally{runtime.destroy();}
